<script setup>
import { $api } from '@/utils/api'
import ChampionshipEventManager from '@/components/ChampionshipEventManager.vue'
import ChampionshipOperations from '@/components/ChampionshipOperations.vue'
const loading=ref(false),saving=ref(false),data=reactive({championships:[],categories:[],members:[],facilities:[]}),selected=ref(null),dialog=ref(false),eventDialog=ref(false),categoryDialog=ref(false),categoryManageDialog=ref(false),entryDialog=ref(false),entryEvent=ref(null),errors=ref({}),operationError=ref('')
const form=reactive({name:'',season:new Date().getFullYear().toString(),starts_on:'',ends_on:'',age_cutoff_on:'',entries_open_at:'',entries_close_at:'',regulations:''})
const eventForm=reactive({name:'',discipline:'singles',gender_rule:'open',age_category_id:null,draw_format:'knockout',entry_fee_rands:0,fee_basis:'player',capacity:null,seed_count:0})
const categoryForm=reactive({name:'',minimum_age:null,maximum_age:null,combined_minimum_age:null,team_age_rule:'both'})
const entryForm=reactive({member_ids:[]})
const drawFormats=[{title:'Knockout',value:'knockout'},{title:'Round robin',value:'round_robin'},{title:'Round robin → elimination',value:'group_knockout'},{title:'Consolation',value:'consolation'},{title:'Feed-in',value:'feed_in'},{title:'Compass',value:'compass'},{title:'Monrad',value:'monrad'},{title:'Double elimination',value:'double_elimination'},{title:'Swiss',value:'swiss'},{title:'Custom',value:'custom'}]
const standardCategories=['Open','Under 10','Under 12','Under 14','Under 16','Under 18','30+','35+','40+','45+','50+','55+','60+','65+']
const money=c=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format((c||0)/100)
const formatDate=value=>value?new Intl.DateTimeFormat('en-ZA',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value)):''
async function load(){loading.value=true;try{Object.assign(data,await $api('/championships'));if(selected.value)selected.value=data.championships.find(x=>x.id===selected.value.id)||data.championships[0];else selected.value=data.championships[0]}finally{loading.value=false}}
async function save(){saving.value=true;errors.value={};try{await $api('/championships',{method:'POST',body:form});dialog.value=false;await load()}catch(e){errors.value=e?.data?.errors||{}}finally{saving.value=false}}
async function saveEvent(){saving.value=true;errors.value={};try{const {entry_fee_rands,...fields}=eventForm;const body={...fields,age_category_id:eventForm.age_category_id||null,capacity:eventForm.capacity||null,entry_fee_cents:Math.round((Number(entry_fee_rands)||0)*100),seed_count:Number(eventForm.seed_count)||0};await $api(`/championships/${selected.value.id}/events`,{method:'POST',body});eventDialog.value=false;Object.assign(eventForm,{name:'',discipline:'singles',gender_rule:'open',age_category_id:null,draw_format:'knockout',entry_fee_rands:0,fee_basis:'player',capacity:null,seed_count:0});await load()}catch(e){errors.value=e?.data?.errors||{general:[e?.data?.message||'Unable to save the event.']};if(errors.value.entry_fee_cents)errors.value.entry_fee_rands=errors.value.entry_fee_cents}finally{saving.value=false}}
async function saveCategory(){saving.value=true;errors.value={};try{const category=await $api('/championship-age-categories',{method:'POST',body:categoryForm});categoryDialog.value=false;eventForm.age_category_id=category.id;Object.assign(categoryForm,{name:'',minimum_age:null,maximum_age:null,combined_minimum_age:null,team_age_rule:'both'});await load()}catch(e){errors.value=e?.data?.errors||{}}finally{saving.value=false}}
function openChampionship(championship){selected.value=championship;errors.value={};eventDialog.value=true}
function openEventDialog(){errors.value={};eventDialog.value=true}
function openCategoryDialog(){categoryManageDialog.value=false;errors.value={};categoryDialog.value=true}
function openEntry(event){entryEvent.value=event;entryForm.member_ids=[];errors.value={};entryDialog.value=true}
async function saveEntry(){saving.value=true;errors.value={};try{await $api(`/championship-events/${entryEvent.value.id}/entries`,{method:'POST',body:entryForm});entryDialog.value=false;await load()}catch(e){errors.value=e?.data?.errors||{general:[e?.data?.message||'Unable to add the entry.']}}finally{saving.value=false}}
async function reviewEntry(entry,changes){operationError.value='';try{await $api(`/championship-entries/${entry.id}`,{method:'PATCH',body:{status:entry.status,payment_status:entry.payment_status,...changes}});await load()}catch(e){operationError.value=e?.data?.message||'Unable to update the entry.'}}
async function archiveEvent(event){if(!confirm(`Archive ${event.name}?`))return;operationError.value='';try{await $api(`/championship-events/${event.id}/archive`,{method:'PATCH'});await load()}catch(e){operationError.value=e?.data?.errors?.event?.[0]||e?.data?.message||'Unable to archive the event.'}}
async function deleteEvent(event){if(!confirm(`Permanently delete ${event.name}?`))return;operationError.value='';try{await $api(`/championship-events/${event.id}`,{method:'DELETE'});await load()}catch(e){operationError.value=e?.data?.errors?.event?.[0]||e?.data?.message||'Unable to delete the event.'}}
async function deleteCategory(category){if(!confirm(`Permanently delete ${category.name}?`))return;operationError.value='';try{await $api(`/championship-age-categories/${category.id}`,{method:'DELETE'});await load()}catch(e){operationError.value=e?.data?.errors?.category?.[0]||e?.data?.message||'Unable to delete the category.'}}
async function deleteChampionship(championship){if(!confirm(`Permanently delete ${championship.name} and its empty events?`))return;operationError.value='';try{await $api(`/championships/${championship.id}`,{method:'DELETE'});if(selected.value?.id===championship.id)selected.value=null;await load()}catch(e){operationError.value=e?.data?.errors?.championship?.[0]||e?.data?.message||'Unable to delete the championship.'}}
const eligibleEntries=event=>event.entries.filter(entry=>['pending','accepted'].includes(entry.status)&&['paid','waived','not_required'].includes(entry.payment_status)).length
const minimumDrawEntries=event=>event.draw_format==='group_knockout'?4:2
async function lifecycle(status){await $api(`/championships/${selected.value.id}/status`,{method:'PATCH',body:{status}});await load()}
async function generate(event){operationError.value='';try{await $api(`/championship-events/${event.id}/draws`,{method:'POST'});await load()}catch(e){operationError.value=e?.data?.errors?.draw?.[0]||e?.data?.message||'Unable to generate the draw.'}}
async function publish(draw){await $api(`/championship-draws/${draw.id}/publish`,{method:'POST'});await load()}
onMounted(load)
watch(()=>form.starts_on,value=>{if(value&&!form.age_cutoff_on)form.age_cutoff_on=value})
</script>
<template><div><div class="d-flex justify-space-between align-center mb-6"><div><h1 class="text-h3">Club Championships</h1><p class="text-medium-emphasis">Entries, draws, scheduling, order of play, results and live tournament operations.</p></div><div class="d-flex gap-2"><VBtn variant="tonal" prepend-icon="tabler-tags" @click="openCategoryDialog">New category</VBtn><VBtn prepend-icon="tabler-plus" @click="errors={};dialog=true">New championship</VBtn></div></div><VAlert v-if="operationError" type="error" variant="tonal" closable class="mb-4" @click:close="operationError=''">{{operationError}}</VAlert>
<VRow><VCol cols="12" md="4"><VCard :loading="loading"><VCardTitle>Championships</VCardTitle><VDivider/><VList nav><VListItem v-for="c in data.championships" :key="c.id" :active="selected?.id===c.id" title="Open championship and add an event" @click="openChampionship(c)"><VListItemTitle>{{c.name}}</VListItemTitle><VListItemSubtitle>{{formatDate(c.starts_on)}} – {{formatDate(c.ends_on)}}</VListItemSubtitle><template #append><div class="d-flex align-center gap-1"><VChip size="small">{{c.status}}</VChip><VIcon icon="tabler-chevron-right" size="18"/><VBtn icon="tabler-trash" size="x-small" color="error" variant="text" title="Delete championship" @click.stop="deleteChampionship(c)"/></div></template></VListItem></VList><VCardText v-if="!data.championships.length">No championships configured.</VCardText></VCard></VCol>
<VCol cols="12" md="8"><template v-if="selected"><VCard class="mb-4"><VCardTitle class="d-flex flex-wrap align-center gap-2"><span class="me-auto">{{selected.name}}</span><ChampionshipOperations :championship="selected"/><VBtn size="small" prepend-icon="tabler-plus" @click="openEventDialog">Add event</VBtn></VCardTitle><VCardText><div class="d-flex gap-2 flex-wrap"><VBtn v-for="s in ['draft','entries_open','entries_closed','draw_published','in_progress','completed','archived']" :key="s" size="small" :variant="selected.status===s?'flat':'tonal'" @click="lifecycle(s)">{{s.replaceAll('_',' ')}}</VBtn></div></VCardText></VCard>
<ChampionshipEventManager v-for="event in selected.events" :key="event.id" :event="event" :championship="selected" :categories="data.categories" @refresh="load" @error="message=>operationError=message" @add-entry="openEntry"/></template><VAlert v-else type="info" variant="tonal">Create a championship to begin.</VAlert></VCol></VRow>
<VDialog v-model="dialog" max-width="760"><VCard><VCardTitle class="pa-6">New championship</VCardTitle><VCardText><VAlert v-if="Object.keys(errors).length" type="error" variant="tonal" class="mb-4">Please correct the highlighted fields.</VAlert><VRow><VCol cols="8"><VTextField v-model="form.name" label="Name" :error-messages="errors.name"/></VCol><VCol cols="4"><VTextField v-model="form.season" label="Season" :error-messages="errors.season"/></VCol><VCol cols="4"><VTextField v-model="form.starts_on" type="date" label="Starts" :error-messages="errors.starts_on"/></VCol><VCol cols="4"><VTextField v-model="form.ends_on" type="date" label="Ends" :error-messages="errors.ends_on"/></VCol><VCol cols="4"><VTextField v-model="form.age_cutoff_on" type="date" label="Age cut-off" :error-messages="errors.age_cutoff_on"/></VCol><VCol cols="12"><VTextarea v-model="form.regulations" label="Regulations" :error-messages="errors.regulations"/></VCol></VRow></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="tonal" @click="dialog=false">Cancel</VBtn><VBtn :loading="saving" @click="save">Create</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="eventDialog" max-width="760"><VCard><VCardTitle class="pa-6">Add event</VCardTitle><VCardText><VAlert v-if="Object.keys(errors).length" type="error" variant="tonal" class="mb-4">{{errors.general?.[0]||'Please correct the highlighted fields.'}}</VAlert><VRow><VCol cols="12"><VTextField v-model="eventForm.name" label="Event name" :error-messages="errors.name"/></VCol><VCol cols="6"><VSelect v-model="eventForm.discipline" :items="['singles','doubles']" label="Discipline" :error-messages="errors.discipline"/></VCol><VCol cols="6"><VSelect v-model="eventForm.gender_rule" :items="['open','male','female','mixed']" label="Category" :error-messages="errors.gender_rule"/></VCol><VCol cols="6"><div class="d-flex gap-2"><VSelect v-model="eventForm.age_category_id" :items="data.categories" item-title="name" item-value="id" label="Age category" clearable :error-messages="errors.age_category_id"/><VBtn icon="tabler-plus" variant="tonal" title="New age category" @click="categoryDialog=true"/></div></VCol><VCol cols="6"><VSelect v-model="eventForm.draw_format" :items="drawFormats" label="Draw format" :error-messages="errors.draw_format"/></VCol><VCol cols="4"><VTextField v-model.number="eventForm.entry_fee_rands" type="number" min="0" step="0.01" prefix="R" label="Entry fee" :error-messages="errors.entry_fee_rands"/></VCol><VCol cols="4"><VSelect v-model="eventForm.fee_basis" :items="['player','team']" label="Fee basis" :error-messages="errors.fee_basis"/></VCol><VCol cols="4"><VTextField v-model.number="eventForm.seed_count" type="number" label="Seeds" :error-messages="errors.seed_count"/></VCol></VRow></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="tonal" @click="eventDialog=false">Cancel</VBtn><VBtn :loading="saving" @click="saveEvent">Save event</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="categoryDialog" max-width="620"><VCard><VCardTitle class="pa-6">New age category</VCardTitle><VCardText><VRow><VCol cols="12"><VTextField v-model="categoryForm.name" label="Category name" placeholder="e.g. 70+ or Under 8" :error-messages="errors.name"/></VCol><VCol cols="6"><VTextField v-model.number="categoryForm.minimum_age" type="number" label="Minimum age" clearable/></VCol><VCol cols="6"><VTextField v-model.number="categoryForm.maximum_age" type="number" label="Maximum age" clearable/></VCol><VCol cols="6"><VTextField v-model.number="categoryForm.combined_minimum_age" type="number" label="Combined team age" clearable/></VCol><VCol cols="6"><VSelect v-model="categoryForm.team_age_rule" :items="['both','youngest','oldest']" label="Doubles age rule"/></VCol></VRow></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="tonal" @click="categoryDialog=false">Cancel</VBtn><VBtn :loading="saving" @click="saveCategory">Save category</VBtn></VCardActions></VCard></VDialog><VDialog v-model="categoryManageDialog" max-width="620"><VCard><VCardTitle class="pa-6">Championship categories</VCardTitle><VList lines="two"><VListItem v-for="category in data.categories" :key="category.id" :title="category.name" :subtitle="standardCategories.includes(category.name)?'Standard category — protected':'Custom category'"><template #append><VBtn v-if="!standardCategories.includes(category.name)" icon="tabler-trash" size="small" color="error" variant="text" title="Delete category" @click="deleteCategory(category)"/></template></VListItem></VList><VCardActions class="pa-6"><VSpacer/><VBtn @click="categoryManageDialog=false">Close</VBtn></VCardActions></VCard></VDialog><VDialog v-model="entryDialog" max-width="620"><VCard><VCardTitle class="pa-6">Add entry to {{entryEvent?.name}}</VCardTitle><VCardText><VAlert v-if="errors.general" type="error" variant="tonal" class="mb-4">{{errors.general[0]}}</VAlert><VSelect v-model="entryForm.member_ids" :items="data.members" item-title="display_name" item-value="id" multiple chips label="Member(s)" :hint="entryEvent?.discipline==='doubles'?'Select exactly two members for one doubles team':'Select one or more members; each becomes a separate singles entry'" persistent-hint :error-messages="errors.member_ids"/></VCardText><VCardActions class="pa-6"><VSpacer/><VBtn variant="tonal" @click="entryDialog=false">Cancel</VBtn><VBtn :loading="saving" @click="saveEntry">{{entryEvent?.discipline==='singles'?'Add selected entries':'Add entry'}}</VBtn></VCardActions></VCard></VDialog></div></template>
